// tf32x3 error-corrected WMMA GEMM tiles (m16n16k8). Each fp32 operand is split
// a = a_hi + a_lo (a_hi = tf32(a), a_lo = tf32(a - a_hi)); the product is
// approximated a*b ~= a_hi*b_hi + a_hi*b_lo + a_lo*b_hi (dropping a_lo*b_lo), so
// three tensor-core MMAs recover ~fp32 accuracy from tf32 hardware. This is the
// accuracy trick the leaderboard tolerance (rtol ~ 20*n*eps32) requires.
// ---------------------------------------------------------------------------
typedef wmma::fragment<wmma::matrix_a, 16, 16, 8, wmma::precision::tf32, wmma::row_major> FragAR;
typedef wmma::fragment<wmma::matrix_a, 16, 16, 8, wmma::precision::tf32, wmma::col_major> FragAC;
typedef wmma::fragment<wmma::matrix_b, 16, 16, 8, wmma::precision::tf32, wmma::row_major> FragBR;
typedef wmma::fragment<wmma::matrix_b, 16, 16, 8, wmma::precision::tf32, wmma::col_major> FragBC;
typedef wmma::fragment<wmma::accumulator, 16, 16, 8, float> FragAcc;

// Group-B bulk trailing with tf32x3 WMMA on the two big GEMMs. V is the CLEAN
// reflector panel (column-major n*nb in P: V[r,i]=P[i*n+r], rows<p+i zeroed,
// diagonal 1). Cs is the column-major chunk (n * ctp, ctp a multiple of 16, tail
// columns zero-padded). Steps:
//   1. W  = V^T @ Cs        (M=nb, N=ctp, K=n)   WMMA tf32x3, A=V^T(=P) row_major
//   2. W' = T^T @ W         (small, SIMT)
//   3. Cs -= V @ W'         (M=n,  N=ctp, K=nb)  WMMA tf32x3, A=V(=P) col_major
// Each warp (group-local warpB in [0,WB)) owns a strided set of 16x16 output
// tiles; all 32 lanes participate in every mma_sync it issues.
static __device__ void qr_la_trailing_tc(
    float* P, float* Tm, float* Cs, float* Ws,
    int p, int nb, int ctp, int n, int t, int nthr, int NB, int wscols, int barid)
{
    const int warpB = t >> 5;
    const int WB = nthr >> 5;
    const int mt_nb = nb / 16;            // m-tiles for step 1 output rows (nb)
    const int nt    = ctp / 16;           // n-tiles (chunk columns)
    const int kt_n  = n / 8;              // k-tiles over n rows

    // ---- Step 1: W[nb x ctp] = V^T @ Cs ----
    // A = V^T : (nb x n) row-major == P (P[i*n+r] = V^T[i,r]), ldm = n.
    // B = Cs  : (n x ctp) col-major (Cs[g*n+r]), ldm = n.
    // W stored col-major in Ws (ldm NB): W[i,g] at Ws[i + g*NB].
    int ntiles1 = mt_nb * nt;
    for (int tile = warpB; tile < ntiles1; tile += WB) {
        int mi = tile / nt;               // 0..mt_nb-1
        int ni = tile % nt;               // 0..nt-1
        FragAcc acc; wmma::fill_fragment(acc, 0.0f);
        for (int kk = 0; kk < kt_n; ++kk) {
            FragAR a; wmma::load_matrix_sync(a, P + (long)mi * 16 * n + kk * 8, n);
            FragBC b; wmma::load_matrix_sync(b, Cs + (long)ni * 16 * n + kk * 8, n);
            FragAR ah, al; FragBC bh, bl;
            #pragma unroll
            for (int e = 0; e < a.num_elements; ++e) {
                float hv = wmma::__float_to_tf32(a.x[e]);
                ah.x[e] = hv; al.x[e] = wmma::__float_to_tf32(a.x[e] - hv);
            }
            #pragma unroll
            for (int e = 0; e < b.num_elements; ++e) {
                float hv = wmma::__float_to_tf32(b.x[e]);
                bh.x[e] = hv; bl.x[e] = wmma::__float_to_tf32(b.x[e] - hv);
            }
            wmma::mma_sync(acc, ah, bh, acc);
            wmma::mma_sync(acc, ah, bl, acc);
            wmma::mma_sync(acc, al, bh, acc);
        }
        // store acc (16x16) to W col-major (Ws, ldm NB). Use mem_col_major.
        wmma::store_matrix_sync(Ws + (long)mi * 16 + (long)ni * 16 * NB, acc, NB,
                                wmma::mem_col_major);
    }
    grp_bar(barid, nthr);

    // ---- Step 2: W''[i,g] = -sum_{l<=i} T[l,i] W[l,g]  (SIMT, NEGATED) ----
    // Negating here lets step 3 fold the subtraction into the accumulator:
    // Cs_new = Cs + V @ W'' = Cs - V @ W' = Cs - delta.
    for (int idx = t; idx < nb * ctp; idx += nthr) {
        int g = idx / nb, i = idx % nb;
        float a = 0.f;
        for (int l = 0; l <= i; ++l) a += Tm[(long)l + (long)i * NB] * Ws[(long)l + (long)g * NB];
        Ws[(long)NB * wscols + (long)i + (long)g * NB] = -a;
    }
    grp_bar(barid, nthr);

    // ---- Step 3: Cs += V @ W''  (== Cs - V @ W') ----
    // A = V : (n x nb) col-major == P (P[i*n+r]=V[r,i]), ldm = n.
    // B = W'': (nb x ctp) col-major in Ws+NB*wscols (ldm NB).
    // Pre-load current Cs tile into the accumulator so the store writes Cs_new.
    int mt_n = n / 16;
    int ntiles3 = mt_n * nt;
    int kt_nb = nb / 8;                    // nb in {16,32} -> exact
    float* Wp = Ws + (long)NB * wscols;
    for (int tile = warpB; tile < ntiles3; tile += WB) {
        int mi = tile / nt;               // 0..mt_n-1  (row tile over n)
        int ni = tile % nt;               // 0..nt-1
        FragAcc acc;
        wmma::load_matrix_sync(acc, Cs + (long)mi * 16 + (long)ni * 16 * n, n,
                               wmma::mem_col_major);   // acc = current Cs tile
        for (int kk = 0; kk < kt_nb; ++kk) {
            int kbase = kk * 8;
            FragAC a; wmma::load_matrix_sync(a, P + (long)mi * 16 + (long)kbase * n, n);
            FragBC b; wmma::load_matrix_sync(b, Wp + kbase + (long)ni * 16 * NB, NB);
            FragAC ah, al; FragBC bh, bl;
            #pragma unroll
            for (int e = 0; e < a.num_elements; ++e) {
                float hv = wmma::__float_to_tf32(a.x[e]);
                ah.x[e] = hv; al.x[e] = wmma::__float_to_tf32(a.x[e] - hv);
            }
            #pragma unroll
            for (int e = 0; e < b.num_elements; ++e) {
                float hv = wmma::__float_to_tf32(b.x[e]);
                bh.x[e] = hv; bl.x[e] = wmma::__float_to_tf32(b.x[e] - hv);
            }
            wmma::mma_sync(acc, ah, bh, acc);
            wmma::mma_sync(acc, ah, bl, acc);
            wmma::mma_sync(acc, al, bh, acc);
        }
        wmma::store_matrix_sync(Cs + (long)mi * 16 + (long)ni * 16 * n, acc, n,
                                wmma::mem_col_major);
    }
    grp_bar(barid, nthr);
}


